INSERT INTO tasks VALUES('t-init-commit','p-gtte',NULL,0,'Initial commit + track plandb.db','git add -A; verify .plandb.db is tracked (explicit negation in .gitignore); initial commit with message ''init: Chief OS — axioms, architecture scaffold, v0 scope, plandb project''. Do NOT push yet — user decides. Record what was committed.','done','shell',3,'default','2026-04-21 20:35:42','2026-04-21 20:35:42','2026-04-21 20:44:12',NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:35:42',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:01:16','2026-04-21 20:44:12');
INSERT INTO tasks VALUES('t-future-protos','p-gtte',NULL,1,'Future: prototype spikes (capability broker, region router, morning brief render, memory graph)','Placeholder for post-scaffold implementation work. Use codex on git worktrees for parallel spikes: (1) capability-broker proof — tiny Rust service with typed cap grants, (2) region-router rule-table — deterministic classifier + tests, (3) morning-brief render — React/Svelte surface over mock data, (4) memory-graph tri-store (SQLite + FAISS + edges). Each spike: own README + CLEANUP date. For agent harness inside these: use opencode (swappable interface).','ready','code',2,NULL,'2026-04-21 20:44:30','2026-04-21 20:44:30',NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:44:30',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:01:18','2026-04-21 20:45:29');
INSERT INTO tasks VALUES('t-model-swap','p-gtte',NULL,0,'Strengthen model-routing swappability in local-vs-cloud + architecture','Edit docs/09-local-vs-cloud.md and docs/02-architecture.md to make ModelBackend abstraction explicit as a first-class architectural primitive. Granularity: system-wide, per-category, per-pack, per-agent, per-call. Control plane deferred to later. Add requirement in docs/requirements/non-functional.md.','done','code',7,'default','2026-04-21 20:18:29','2026-04-21 20:18:29','2026-04-21 20:20:01','{"added":"Model Router as first-class kernel service with 5 granularity levels and swappable backends","edits":["docs/02-architecture.md","docs/09-local-vs-cloud.md"]}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:18:29',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:17:40','2026-04-21 20:20:01');
INSERT INTO tasks VALUES('t-lang-policy','p-gtte',NULL,0,'Document polyglot language policy','Add section in docs/02-architecture.md + docs/requirements/non-functional.md declaring polyglot code strategy: Rust for kernel, Go for network services, TypeScript for surfaces, Python for agents/ML. No OS-startup optimization required for v0.','done','code',5,'default','2026-04-21 20:34:04','2026-04-21 20:34:04','2026-04-21 20:34:10','{"note":"polyglot language policy baked into docs/02-architecture.md and docs/requirements/non-functional.md during t-model-swap and t-reqs","status":"already_done_inline"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:34:04',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:17:41','2026-04-21 20:34:10');
INSERT INTO tasks VALUES('t-agent-fs','p-gtte',NULL,0,'Research: agent-native filesystem design','Deep-dive research: when AI is primary user, how should the filesystem be organized? Axes to investigate: (1) content-addressed primary layout (mem://file/<hash>) vs human folders; (2) local embedding model selection — fastembed-rs, ort+onnx, sentence-transformers, bge-m3, nomic-embed — benchmark speed vs quality on Chief-OS-class CPU; (3) at-rest vs indexed vs hot — what tier? (4) what agents see vs what humans see — two views over one substrate; (5) does ~/Downloads/ live as legacy shim or get absorbed? Output: docs/research/NNNN-agent-native-fs.md + proposed edits to docs/08-memory-substrate.md. Compare with how Plan9, Tahoe-LAFS, IPFS, Cassandra did content-naming. Also check prior art: Genode, Morello, Copland-attested FS.','done','research',6,'default','2026-04-21 20:28:17','2026-04-21 20:28:17','2026-04-21 20:29:08','{"embed_pick":"fastembed-rs + bge-small-en-v1.5","file":"docs/research/2026-04-21-agent-native-fs.md","references":"primitive-rethinks research"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:28:17',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:19:00','2026-04-21 20:29:08');
INSERT INTO tasks VALUES('t-directives','p-gtte',NULL,0,'Create docs/directives/ log for user notes and do periodic audit','Create docs/directives/README.md (append-only log of verbal directives from user — time-stamped). Capture each user comment as an entry. Periodically run an ''audit pass'' that cross-references existing docs against directives and flags where edits are needed. First audit scheduled after t-idx completes. This is the formal capture channel for the user''s ongoing verbal direction.','done','generic',4,'default','2026-04-21 20:34:49','2026-04-21 20:34:49','2026-04-21 20:35:42','{"directives_logged":8,"file":"docs/directives/README.md","resolution_tracking":true}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:34:49',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:19:03','2026-04-21 20:35:42');
INSERT INTO tasks VALUES('t-os-primitives','p-gtte',NULL,0,'Research: AI-native rethink across ALL OS primitives','Broad research and filter: for each OS primitive (filesystem, scheduler, memory, clipboard, shell, notifications, logging, observability, search, sessions, compositor, drivers, DNS, timekeeping, mail, calendar, browser, media), evaluate (a) what changes if AI is primary user, (b) strategic uniqueness vs just ''ported'', (c) v0/v1/v2 impact, (d) viral-demo leverage. Rank by (strategic value × demo leverage) / (engineering cost). Output: docs/research/NNNN-ai-native-primitive-rethinks.md with a prioritized table + picks for v0-v1 integration. Companion edits in docs/02-architecture.md for the top 3.','done','research',7,'default','2026-04-21 20:21:38','2026-04-21 20:21:38','2026-04-21 20:22:50','{"note":"background agent dispatched; will incorporate findings on return","scaffold":"docs/research/2026-04-21-ai-native-primitive-rethinks.md","status":"agent_in_flight"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:21:38',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:20:37','2026-04-21 20:22:50');
INSERT INTO tasks VALUES('t-incorp-primitives','p-gtte',NULL,0,'Incorporate OS-primitives research findings on agent return','When the background research agent returns with AI-native primitive rethinks findings, (1) flesh out docs/research/2026-04-21-ai-native-primitive-rethinks.md with full content, (2) propose edits to docs/02-architecture.md for top-5 picks, (3) open ADRs for any that commit us to a technical choice, (4) update docs/14-risks-open-questions.md with new open questions.','done','code',6,'default','2026-04-21 20:29:08','2026-04-21 20:29:08','2026-04-21 20:31:09','{"adrs_added":["0005","0006","0007"],"architecture_updated":true,"substrate_spine_incorporated":true,"surfaces_updated":true,"v0_scope_updated":true}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:29:08',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:22:53','2026-04-21 20:31:09');
INSERT INTO tasks VALUES('t-5296','p-gtte','t-future-protos',0,'Prototype: Capability Broker (Rust)','Hypothesis: build a minimal Capability Broker in Rust that (a) issues typed scoped bearer-style grants, (b) verifies every call via broker.check, (c) emits signed provenance entries to stdout in in-toto v1 format. Files expected: prototypes/capability-broker/{Cargo.toml,src/main.rs,src/grant.rs,src/check.rs,README.md,measurements.md}. Acceptance: 1000 check() ops in <100ms; grant revoke reflected in next check; fuzz at least 10k inputs with no panic. Worktree: branch proto/capability-broker; own plandb agent (PLANDB_AGENT=codex-cap-broker). Parallel-safe: no shared state with other prototype tasks. References: docs/03-chief-kernel.md (service #2), docs/06-security-model.md, adr/0002.','ready','generic',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:44:37','2026-04-21 20:45:21');
