INSERT INTO tasks VALUES('t-proto-mem','p-gtte',NULL,0,'Prototype: chief-mem memory stack (Rust + PyO3)',unistr('CRITICAL SETUP: export PLANDB_DB=/Users/santoshkumarradha/Documents/agentfield/code/labs/nix/.plandb.db BEFORE any plandb command. Worktree sits at labs/chief-os-mem, sibling to labs/nix; plandb will walk up wrong without this.\u000a---\u000aHypothesis: one Rust crate opens SQLite+sqlite-vec+FTS5 plus iroh-blobs and exposes PyO3 bindings. Implements nodes/edges/vectors/texts SQL schema from adr-0008. Files: prototypes/chief-mem/{Cargo.toml,src/lib.rs,src/schema.sql,src/query.rs,python/chief_mem/__init__.py,tests/*,README.md,measurements.md}. Acceptance: 100k synthetic nodes indexed; p50 query (vector+BM25+graph-walk) < 200ms; Python+Rust both import same .db. Worktree: proto/chief-mem. Dep: validates pure-OSS stack choice from adr-0008. References: docs/08-memory-substrate.md, docs/research/2026-04-21-pure-oss-memory-substrate.md.'),'done','code',6,NULL,'2026-04-21 21:48:12','2026-04-21 21:48:12','2026-04-21 21:48:12','{"commit":"1da20c0","insert_per_sec":13525,"merged":true,"nodes_tested":100000,"pr":"https://github.com/santoshkumarradha/ChiefOS/pull/11"}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:47:32',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:45:35','2026-04-21 21:48:12');
