INSERT INTO tasks VALUES('t-legal-tos','p-gtte',NULL,0,'Legal: draft Terms of Service encoding machine-as-fax posture','Per adr-0004 and docs/15-regulatory-posture.md: ToS must encode (1) every external action is cryptographically signed by user via ceremony, making human the legal actor; (2) ESIGN/UETA/eIDAS compatibility language; (3) GDPR controller/processor clarity (user is controller). External counsel review required before v0 public launch. Files: legal/terms-of-service.md (new dir), legal/privacy-policy.md. Cross-link from docs/15-regulatory-posture.md.','ready','generic',3,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:46:18','2026-04-21 20:46:18');
INSERT INTO tasks VALUES('t-claude-md','p-gtte',NULL,0,'Write CLAUDE.md for this repo (dev workflow for AI agents)','Create /CLAUDE.md at repo root that any AI agent (Claude, Gemini, Codex, etc.) entering this repo reads first. Content: (1) project summary (1 sentence), (2) read-order: AGENTS.md -> CHARTER.md -> docs/INDEX.md -> docs/13-v0-scope-90-day.md, (3) PlanDB usage as source of truth for tasks (commands, conventions), (4) worktree + branch conventions (proto/<slug>, docs/<slug>), (5) how to claim a task (plandb go --agent <handle>), (6) commit-message format, (7) how to restart work in a new session (plandb status --detail), (8) where logs/research/directives land, (9) how to escalate or flag decisions (add to docs/14-risks-open-questions.md decisions-needed table or open ADR).','done','code',8,'default','2026-04-21 20:46:28','2026-04-21 20:46:28','2026-04-21 20:47:32','{"file":"CLAUDE.md","sections":["orientation","plandb-loop","multi-agent","conventions","restart","escalation"]}',NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 20:46:28',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 20:46:24','2026-04-21 20:47:32');
