INSERT INTO tasks VALUES('t-mb-tauri','p-gtte',NULL,0,'Integration: Tauri-wrap Morning Brief (native desktop binary)','CRITICAL: export PLANDB_DB=/Users/santoshkumarradha/Documents/agentfield/code/labs/nix/.plandb.db before any plandb. Worktree: labs/chief-os-tauri. Wrap prototypes/morning-brief in Tauri v2 so it ships as a native desktop binary. Per docs/brand/visual-language.md — non-negotiable design rules. Create ONLY files under prototypes/morning-brief/src-tauri/ (scaffold via tauri init) + tauri.conf.json + update prototypes/morning-brief/package.json with tauri scripts. Do NOT modify prototypes/morning-brief/src/ — that''s another agent''s work (mb-live-api). Bundle fonts in binary at build time (Inter from rsms.me/inter or SIL OFL Inter tarball), drop into src-tauri/fonts/. Register keyboard shortcuts via tauri-plugin-global-shortcut (⌘ Space / Ctrl+Space for Omnibar placeholder, ⌘ . for HAX Inbox placeholder, Esc to reset focus). Native window config: fullscreen flag on release, 1280x800 in dev, titleBarStyle=overlay on mac, decorations=false on Linux kiosk build. Install tauri-plugin-context-menu, tauri-plugin-window-vibrancy. Add build target: ''npm run tauri build'' produces a .app bundle on mac, .AppImage+.deb on Linux. Add a README section ''Running as native app''. Acceptance: npm run tauri dev opens a native window displaying Morning Brief; window is fullscreen in prod; no browser chrome visible; font is bundled (verify via devtools); ⌘+Space logs a ''TODO'' to console (real surface comes later); cargo build of the src-tauri Rust code succeeds; npm run tauri build produces a platform-native bundle. Worktree: branch int/mb-tauri. References: docs/brand/visual-language.md (ESPECIALLY sections 1, 2, 3, 7, 8, 9, 15, 16).','running','code',9,'codex-mb-tauri','2026-04-21 22:21:38','2026-04-21 22:21:38',NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 22:21:38',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 22:19:32','2026-04-21 22:21:38');
INSERT INTO tasks VALUES('t-mb-live-api','p-gtte',NULL,0,'Integration: Morning Brief wired to chief-core HTTP API','CRITICAL: export PLANDB_DB=/Users/santoshkumarradha/Documents/agentfield/code/labs/nix/.plandb.db before any plandb. Worktree: labs/chief-os-mb-api. Only modify files under prototypes/morning-brief/src/ + vite.config.ts + package.json deps. Do NOT touch prototypes/morning-brief/src-tauri/ — that''s another agent''s work (mb-tauri). Add src/api.ts: typed fetch wrapper around chief-core''s 6 routes. Add src/hooks/useBriefState.ts: polls /brief every 3s (SSE later); returns BriefState or loading/error. Modify MorningBrief.tsx to useBriefState() instead of loading mock/brief-state.json directly. Wire NeedsYouCard Review button → POST /approve (ceremony: false for tier-1, true for tier-3). Wire Rewind slider → POST /rewind with duration. Wire CeremonyModal Confirm → POST /approve with ceremony:true. Env: VITE_CHIEF_CORE_URL (default http://127.0.0.1:4711). Fallback behaviour: if /status fails, fall back to mock/brief-state.json with a visible banner at top ''demo mode (no chief-core running)''. Write vitest tests for api.ts and useBriefState with mocked fetch. Keep existing UI look-and-feel; do not redesign. Acceptance: with chief-core running locally, Morning Brief shows live cards generated from POST /intent calls; without, demo-mode banner shows. Approval button actually ships and returns attestation id. Rewind actually reverts state. npm run build clean. Worktree: branch int/mb-live-api.','running','code',9,'codex-mb-live','2026-04-21 22:22:23','2026-04-21 22:22:23',NULL,NULL,NULL,NULL,NULL,0,0,'exponential',1000,NULL,30,'2026-04-21 22:22:23',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-04-21 22:19:32','2026-04-21 22:22:23');
