INSERT INTO learnings VALUES('c-kny6','p-gtte',NULL,'default','pattern','Pre-commit hook test: verifying auto-export works end-to-end.','2026-04-21 21:35:57');
INSERT INTO learnings VALUES('c-m9b4','p-gtte',NULL,'default','discovery','proto/events completed: Signed Typed Event Log with Merkle chain. Implemented ADR-0005 substrate: 7 event kinds, fjall storage, Ed25519 signing, chain verification with tampering detection. Concurrent safety tested. Benchmark: ~900 events/sec single-threaded. PR #10 opened. Ready for integration into chief-kernel.','2026-04-21 21:38:01');
INSERT INTO learnings VALUES('c-1y56','p-gtte','t-chief-core-contracts','codex-chief-core','discovery','chief-core integration notes: prototypes expose NullHarness async API, chief_mem::ChiefMem sync SQLite store, chief_event_log_proto::EventLog with CapabilityCheck/ToolCall/UIAction events, chief_region_router_proto deterministic classify(), and chief_inference Attestor/EphemeralDeviceKey/verify primitives. chief-inference InferenceRouter is lower-level; chief-core can build a small stub inference adapter that calls LocalLlamaCppStub and signs CanonicalPrompt/CanonicalOutput with Attestor. Prototype gap: ChiefMem has no public tombstone method, so chief-core should maintain queue/card state and can add its own small SQLite metadata store under runtime/ for reversible queue state.','2026-04-21 22:03:01');
INSERT INTO learnings VALUES('c-0tg1','p-gtte',NULL,'default','discovery','Docker validation: 4 bugs found in original Dockerfile/compose: (1) placeholder SHA256 for Qwen model would fail on first build — real sha256 is 626b4a6678b86442240e33df819e00132d3ba7dddfe1cdc4fbb18e0a9615c62d (from HF Hub x-linked-etag); (2) Rust 1.82 base image too old — rmp 0.8.15 requires edition2024 (Rust 1.85+) — bumped to rust:1.89-slim-bookworm; (3) chief-core defaults to --bind 127.0.0.1:4711 which isn''t reachable from host port-mapping — wrap in entrypoint.sh that execs with --bind 0.0.0.0:4711; (4) no static-file server for Morning Brief on port 5173 — Dockerfile copied dist to /app/morning-brief but nothing served it — added busybox-static and run busybox httpd on :5173 from entrypoint. Also: Docker Desktop''s default IPv6 port mapping ''::]:5173->5173'' hijacks localhost-over-v6 since busybox httpd is IPv4-only; pin host side to ''0.0.0.0:PORT:PORT'' in compose to force IPv4-only host mapping. Fixed demo-docker.sh payload key (prompt -> text) to match routes.rs. Validation results: build ~200s cold, image 4.35GB, boot-to-healthy ~7s, memory 3MB (stub backend), all 4 endpoints pass.','2026-04-21 22:27:09');
